'use client';

import { TruckIcon } from '@/components/core/truck-icon';

export default function TruckIconBasic() {
  return (
    <div className='flex flex-col items-center gap-8 p-8'>
      <div className='flex flex-col items-center gap-2'>
        <TruckIcon
          size={48}
          animationType='drive'
          className='text-orange-600'
        />
        <p className='text-muted-foreground text-sm'>Drive (Slide)</p>
      </div>

      <div className='flex flex-col items-center gap-2'>
        <TruckIcon size={48} animationType='bounce' className='text-blue-600' />
        <p className='text-muted-foreground text-sm'>Bounce (Rough Road)</p>
      </div>
    </div>
  );
}

'use client';

import { motion, useAnimation } from 'motion/react';
import { Truck } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useEffect, useState } from 'react';

interface TruckIconProps {
  className?: string;
  color?: string;
  size?: number;
  isAnimating?: boolean;
  startOnHover?: boolean;
  animationType?: 'drive' | 'bounce';
}

export function TruckIcon({
  className,
  color = 'currentColor',
  size = 24,
  isAnimating = false,
  startOnHover = true,
  animationType = 'drive',
}: TruckIconProps) {
  const controls = useAnimation();
  const [isHovered, setIsHovered] = useState(false);
  const shouldAnimate = isAnimating || (startOnHover && isHovered);

  useEffect(() => {
    if (shouldAnimate) {
      if (animationType === 'drive') {
        controls.start({
          x: [0, 3, -3, 0],
          transition: {
            duration: 0.5,
            repeat: Infinity,
            repeatType: 'loop',
            ease: 'easeInOut',
            repeatDelay: 0.5,
          },
        });
      } else if (animationType === 'bounce') {
        controls.start({
          y: [0, -2, 0, -1, 0],
          transition: {
            duration: 0.5,
            repeat: Infinity,
            repeatType: 'loop',
            ease: 'easeInOut',
            repeatDelay: 0.2,
          },
        });
      }
    } else {
      controls.stop();
      controls.set({ x: 0, y: 0 });
    }
  }, [shouldAnimate, animationType, controls]);

  return (
    <div
      className={cn(
        'relative flex cursor-pointer items-center justify-center select-none',
        className
      )}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <motion.div animate={controls}>
        <Truck size={size} color={color} />
      </motion.div>
    </div>
  );
}
